<body>

  <!-- Cabeçalho com a logo -->
  <header class="header-top">
    <a class="logo" href="#" aria-label="Página inicial">
      <img class="logo-img" src="logo.png" alt="Logo Louans" width="48" height="48">
      <span>LOUANS</span>
    </a>
    <span class="tag">Diagnóstico</span>
  </header>

  <!-- Barrinha de progresso (criada pelo JS) -->
  <div id="prog" class="progress" role="navigation" aria-label="Progresso do formulário"></div>

  <!-- Conteúdo principal (as telas são montadas pelo JavaScript) -->
  <div id="app"></div>

  <footer class="footer">louans.com · Todos os direitos reservados</footer>

<script>
(function () {
  'use strict';

  /* ===============================================================
     FORMULÁRIO LOUANS — PLUG & PLAY
     Para funcionar, edite APENAS isto:
       1) BUY_URL ...................... link da sua página de pagamento (Hotmart, Kiwify, Stripe...)
       2) FINAL_VIDEO.id ............... ID do seu vídeo no YouTube
       3) SLOTS ........................ As perguntas (pode trocar livremente)
     Arquivo necessário na MESMA pasta: logo.png (ou .jpg / .svg)
     =============================================================== */

  var LS = 'LouAnsFlow_v1';

  /* -------------------------- CONFIGURAÇÃO -------------------------- */
  var CHECKPOINT = '__NENHUM_LINK_DE_COMPRA_DEFINIDO__'; // SINAL de que ninguém configurou ainda
  var BUY_URL = CHECKPOINT;                              // >>> SUBSTITUA pelo link real, ex.: https://kiwify.com.br/abc123
  var FINAL_VIDEO = {
    id: 'SEU-ID-DO-VÍDEO-AQUI', // ex.: abc123XYZ  OU  https://www.youtube.com/watch?v=dXx...
    titulo: 'Veja na prática: resultados reais',
    nota: 'Relatos reais de pessoas que deram o primeiro passo. Pode pausar e retomar.'
  };

  /* ------------------------- AS 4 PERGUNTAS ------------------------- */
  var SLOTS = [
    {
      title: 'Como você está se sentindo em relação ao seu físico HOJE?',
      hint: 'Só um termômetro do seu momento. O que responder aqui fica apenas comigo.',
      options: [
        { k: 'a', label: 'MUITO CONTENTE',      emoji: '😁' },
        { k: 'b', label: 'PODERIA MELHORAR',    emoji: '😊' },
        { k: 'c', label: 'NADA CONTENTE',       emoji: '😑' },
        { k: 'd', label: 'MUITO MAL',           emoji: '😔' },
      ]
    },
    {
      title: 'Qual é o seu nível de motivação para começar AGORA?',
      options: [
        { k: 'e', label: 'TOTALMENTE MOTIVADO', emoji: '🚀' },
        { k: 'f', label: 'MOTIVADO E PRONTO',   emoji: '💪' },
        { k: 'g', label: 'MEIO NEUTRO',         emoji: '😐' },
        { k: 'h', label: 'SEM VONTADE NO MOMENTO', emoji: '😕' },
      ]
    },
    {
      title: 'Você já tentou trabalhar a sua aparência antes?',
      options: [
        { k: 'i', label: 'NUNCA TENTEI',        emoji: '😌' },
        { k: 'j', label: 'JÁ TIVE ÓTIMOS RESULTADOS', emoji: '🙂' },
        { k: 'k', label: 'JÁ TENTEI, MAS NADA DEU CERTO', emoji: '😕' },
        { k: 'l', label: 'JÁ DESISTI MAIS DE UMA VEZ', emoji: '😞' },
      ]
    },
    {
      title: 'O que mais tem travado a sua decisão?',
      options: [
        { k: 'm', label: 'FALTA DE TEMPO',      emoji: '⏱️' },
        { k: 'n', label: 'FALTA DE DINHEIRO',  emoji: '💸' },
        { k: 'o', label: 'AINDA NÃO VI RESULTADO', emoji: '😕' },
        { k: 'p', label: 'MEDO DE COMEÇAR DO ZERO', emoji: '😰' },
      ]
    }
  ];

  /* ------------------------- ESTADO (salvo automaticamente) --------- */
  var state = { answers: {}, cur: 0, choices: {} };
  try {
    var data = localStorage.getItem(LS);
    state = data ? JSON.parse(data) : { answers: {}, cur: 0, choices: {} };
  } catch (e) {
    state.cur = 0;
  }
  if (state.cur > SLOTS.length - 1) state.cur = SLOTS.length - 1;


  /* ============================== AUXILIARES ============================== */
  function persist() {
    localStorage.setItem(LS, JSON.stringify({ answers: state.answers, cur: state.cur }));
  }

  function escapeHtml(s) {
    var map = { '&': '&', '<': '<', '>': '>', '"': '"', "'": "'" };
    return String(s).replace(/[&<>"']/g, function (c) { return map[c] || c; });
  }

  function updateStep(i, key) {
    var step = document.querySelector('#app .step[data-step="' + i + '"]');
    if (!step) return;
    var opts = [...step.querySelectorAll('.option')];
    opts.forEach(function (o) { o.classList.toggle('checked', o.dataset.key === key); });

    // foco visual na alternativa marcada
    var sel = null;
    if (key != null && state.choices[i] == key) {
      sel = step.querySelector('.option[data-key="' + key + '"]');
    }
    if (sel) {
      opts.forEach(function (o) { o.classList.remove('focused'); });
      sel.classList.add('focused');
    } else if (document.querySelector('.option.focused')) {
      document.querySelector('.option.focused').classList.remove('focused');
    }
    focusedOption = sel;

    var acts = step.parentNode.querySelector('.actions');
    if (!acts) return;
    var curQ = SLOTS[i];
    var complete = curQ && curQ.options.every(function (o) {
      var kk = state.choices[i] || '';
      return kk != '' && kk != o.k;
    });
    var canAdvance = complete && (i >= SLOTS.length - 1); // pode mostrar "Próxima"?
    var bt = document.getElementById('btNext');
    if (bt) { bt.style.display = canAdvance ? '' : 'none'; }
    if (bt && !complete && i < SLOTS.length - 1) { bt.setAttribute('aria-busy', 'true'); }
    var bb = document.getElementById('btBack');
    if (bb) bb.style.display = i > 0 ? '' : 'none';
  }

  function focusFirst() {
    var i = state.cur;
    var node = i < SLOTS.length ? document.querySelector('#app .step[data-step="' + i + '"]') : null;
    if (node && node.querySelector('.option[data-key]')) {
      node.querySelector('.option[data-key]').focus();
    } else if (document.getElementById('btBuy')) {
      document.getElementById('btBuy').focus();
    }
  }

  var focusedOption = null;

  function select(key) {
    var i = state.cur;
    if (i >= SLOTS.length) return; // já estamos na tela final
    var q = SLOTS[i];
    var m = q.options.find(function (o) { return o.k === key; });
    if (!m) return;
    var step = document.querySelector('#app .step[data-step="' + i + '"]');
    if (!step) return;
    var radio = step.querySelector('input[name="q' + i + '"][value="' + key + '"]');
    if (radio && radio.checked) return;
    radio.checked = true;
    state.choices[i] = key;
    persist();
    updateStep(i, key);
  }

  function nextAction() {
    var i = state.cur;
    if (i >= SLOTS.length - 1) return; // já na tela do vídeo
    var q = SLOTS[i];
    var complete = q.options.every(function (o) {
      var kk = state.choices[i] || '';
      return kk != '' && kk != o.k;
    });
    if (!complete) {
      showAlert('Escolha uma alternativa antes de continuar.');
      return;
    }
    state.cur = i + 1;
    persist();
    hideAlert();
    renderPage();
    focusFirst();
  }

  function goBack() {
    if (state.cur <= 0) return;
    state.cur--; persist(); hideAlert(); renderPage(); focusFirst();
  }

  function showAlert(msg) {
    var acts = document.querySelector('.actions');
    if (!acts) return;
    var existing = document.querySelector('.actions .alert');
    if (existing) existing.remove();
    var box = document.getElementById('ambox');
    if (!box) {
      box = document.createElement('div');
      box.className = 'alert';
      var p = document.createElement('p');
      p.id = 'amtext';
      p.textContent = msg;
      box.appendChild(p);
      acts.insertBefore(box, acts.firstChild); // coloca o aviso acima dos botões
    }
    box.classList.add('show');
  }
  function hideAlert() {
    var b = document.getElementById('ambox');
    if (b) b.classList.remove('show');
  }

  /* ===================== RENDERIZA TODA A PÁGINA ===================== */
  function renderPage() {
    var app = document.getElementById('app');
    var n = Math.min(state.cur + 1, SLOTS.length);
    app.innerHTML = '';

    for (var i = 0; i < n; i++) {
      if (i < SLOTS.length) {
        var q = SLOTS[i], sel = state.choices[i] || null;
        app.innerHTML +=
          '<section class="step" aria-labelledby="qh' + i + '" data-step="' + i + '">' +
            '<div class="step-head">' +
              '<h2 id="qh' + i + '">' + escapeHtml(q.title) + '</h2>' +
            '</div>' +
            (q.hint ? '<p class="hint">' + escapeHtml(q.hint) + '</p>' : '') +
            '<div class="opts">' +
              q.options.map(function (o) {
                var cls = sel && sel === o.k ? 'checked' : '';
                return `<div class="option ${cls}" data-key="${o.k}" data-num="${i}" role="radio" aria-checked="${cls === 'checked' ? 'true' : 'false'}" tabindex="0">
                  <input type="radio" id="q${i}_${o.k}" name="q${i}" value="${o.k}" aria-label="${escapeHtml(o.label)}">
                  <span class="badge" tabindex="-1"></span>
                  <label class="lbl">
                    <span class="emoji" aria-hidden="true">${escapeHtml(o.emoji)}</span>
                    <span>${escapeHtml(o.label)}</span>
                  </label>
                </div>`;
              }).join('') +
            '</div>' +
          '</section>';
      }
    }

    /* ---------- TELA FINAL: VÍDEO (VSL) + BOTÃO DE COMPRA ---------- */
    if (state.cur >= SLOTS.length - 1) {
      var vid = FINAL_VIDEO.id.trim();
      var src;
      if (vid.indexOf('http') >= 0) src = vid;
      else if (/^https?:\/\//.test(vid)) src = vid;
      else if (/\byoutu\.be/i.test(vid)) {
        vid = vid.replace(/[^\?]+\?(?==&|$)/, '').split('?')[0];
        src = 'https://www.youtube.com/watch?v=' + encodeURIComponent(vid);
      } else {
        src = 'https://www.youtube.com/watch?v=' + encodeURIComponent(vid);
      }

      app.innerHTML +=
        '<section class="step" aria-labelledby="fin">' +
          '<div class="step-head">' +
            '<h3>Sua transformação em vídeo</h3>' +
            '<p class="hint">' + escapeHtml(FINAL_VIDEO.nota || '') + '</p>' +
          '</div>' +
          '<div class="frame-vi">' +
            '<iframe src="' + src + '" title="Vídeo oficial Louans" frameborder="0" allow="autoplay; fullscreen" loading="lazy" allowfullscreen></iframe>' +
          '</div>' +
          '<div class="actions">' +
            '<div class="msg" id="ambox"></div>' +        // espaço reservado para avisos
            '<button class="btn buy" id="btBuy" aria-label="Ir para a página de compra">QUERO COMPRAR AGORA ▶️</button>' +
          '</div>' +
        '</section>';
    }

    /* ---------- PROGRESSO ------------------ */
    var prog = document.getElementById('prog');
    if (prog) {
      prog.innerHTML = Array.from({ length: 5 }, function (_, idx) {
        if (idx < state.cur) return '<div class="dot done"></div>';
        return '<div class="dot active"></div>';
      }).join('');
    }

    /* ---------- BOTÕES DE NAVEGAÇÃO -------- */
    var curIdx = state.cur;
    var acts = document.querySelector('.actions');
    if (!acts) return;
    var curNode = curIdx < SLOTS.length ? document.querySelector('#app .step[data-step="' + curIdx + '"]') : null;
    var curQ = curIdx < SLOTS.length ? SLOTS[curIdx] : null;
    var complete = curQ && curQ.options.every(function (o) {
      var kk = state.choices[curIdx] || '';
      return kk != '' && kk != o.k;
    });
    var btNext = document.getElementById('btNext');
    if (btNext) {
      var podeAvancar = complete && (curIdx >= SLOTS.length - 1);
      btNext.style.display = podeAvancar ? '' : 'none';
