            (q.hint ? '<p class="hint">' + escapeHtml(q.hint) + '</p>' : '') +
            '<div class="opts">' +
              q.options.map(function (o) {
                var cls = sel && sel === o.k ? 'checked' : '';
                return `<div class="option ${cls}" data-key="${o.k}" data-num="${i}" role="radio" aria-checked="${cls === 'checked' ? 'true' : 'false'}" tabindex="0">
                  <input type="radio" id="q${i}_${o.k}" name="q${i}" value="${o.k}" aria-label="${escapeHtml(o.label)}">
                  <span class="badge" tabindex="-1"></span>
                  <label class="lbl">
                    <span class="emoji" aria-hidden="true">${escapeHtml(o.emoji)}</span>
                    <span>${escapeHtml(o.label)}</span>
                  </label>
                </div>`;
              }).join('') +
            '</div>' +
          '</section>';
      }
    }

    /* ---------- TELA FINAL: VÍDEO (VSL) + BOTÃO DE COMPRA ---------- */
    if (state.cur >= SLOTS.length - 1) {
      var vid = FINAL_VIDEO.id.trim();
      var src;
      if (vid.indexOf('http') >= 0) src = vid;
      else if (/^https?:\/\//.test(vid)) src = vid;
      else if (/\byoutu\.be/i.test(vid)) {
        vid = vid.replace(/[^\?]+\?(?==&|$)/, '').split('?')[0];
        src = 'https://www.youtube.com/watch?v=' + encodeURIComponent(vid);
      } else {
        src = 'https://www.youtube.com/watch?v=' + encodeURIComponent(vid);
      }

      app.innerHTML +=
        '<section class="step" aria-labelledby="fin">' +
          '<div class="step-head">' +
            '<h3>Sua transformação em vídeo</h3>' +
            '<p class="hint">' + escapeHtml(FINAL_VIDEO.nota || '') + '</p>' +
          '</div>' +
          '<div class="frame-vi">' +
            '<iframe src="' + src + '" title="Vídeo oficial Louans" frameborder="0" allow="autoplay; fullscreen" loading="lazy" allowfullscreen></iframe>' +
          '</div>' +
          '<div class="actions">' +
            '<div class="msg" id="ambox"></div>' +        // espaço reservado para avisos
            '<button class="btn buy" id="btBuy" aria-label="Ir para a página de compra">QUERO COMPRAR AGORA ▶️</button>' +
          '</div>' +
        '</section>';
    }

    /* ---------- PROGRESSO ------------------ */
    var prog = document.getElementById('prog');
    if (prog) {
      prog.innerHTML = Array.from({ length: 5 }, function (_, idx) {
        if (idx < state.cur) return '<div class="dot done"></div>';
        return '<div class="dot active"></div>';
      }).join('');
    }

    /* ---------- BOTÕES DE NAVEGAÇÃO -------- */
    var curIdx = state.cur;
    var acts = document.querySelector('.actions');
    if (!acts) return;
    var curNode = curIdx < SLOTS.length ? document.querySelector('#app .step[data-step="' + curIdx + '"]') : null;
    var curQ = curIdx < SLOTS.length ? SLOTS[curIdx] : null;
    var complete = curQ && curQ.options.every(function (o) {
      var kk = state.choices[curIdx] || '';
      return kk != '' && kk != o.k;
    });
    var btNext = document.getElementById('btNext');
    if (btNext) {
      var podeAvancar = complete && (curIdx >= SLOTS.length - 1);
      btNext.style.display = podeAvancar ? '' : 'none';
      if (btNext.disabled) btNext.setAttribute('aria-busy', 'true');
    }
    var bb = document.getElementById('btBack');
    if (bb) bb.style.display = curIdx > 0 ? '' : 'none';
  }
})();


/* ===================== EVENTOS ===================== */
document.addEventListener('click', function (e) {
  var d = e.target.closest('.option');
  if (!d) return;
  var k = d.dataset.key;
  if (k) select(k);
});

document.getElementById('btNext').addEventListener('click', nextAction);
document.getElementById('btBack').addEventListener('click', goBack);
document.getElementById('btBuy').addEventListener('click', buy);

document.addEventListener('keydown', function (e) {
  var el = document.activeElement;
  if (!el || !el.matches('.option')) return;
  var step = el.closest('[data-step]');
  if (!step) return;
  var i = parseInt(step.dataset.step, 10);
  var q = SLOTS[i];
  var opts = [...q.options];
  var curK = el.dataset.key;
  var pos = opts.findIndex(function (o) { return o.k === curK; });

  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    var radio = step.querySelector('input[name="q' + i + '"][value="' + curK + '"]');
    radio.checked = true;
    select(curK);
    return;
  }
  if (e.key === 'ArrowDown') { pos = (pos + 1) % opts.length; }
  else if (e.key === 'ArrowUp') { pos = (pos - 1 + opts.length) % opts.length; }
  else return;

  if (pos < 0 || pos >= opts.length) return;
  var t = opts[pos];
  if (t.k !== curK) {
    var radio = step.querySelector('input[name="q' + i + '"][value="' + t.k + '"]');
    radio.checked = true;
    select(t.k);
  }
});

function buy() {
  var url = prompt('Informe o link da sua página de pagamento (Hotmart, Kiwify, Stripe etc.).\nEm branco = será usado o link configurado no início do código.');
  var link = (url && url.trim() !== '') ? url.trim() : null;
  link = link || BUY_URL.trim();

  if (link === CHECKPOINT) {
    link = null;
    showAlert('Ainda não há link de compra configurado. Basta trocar o valor de BUY_URL (linhas iniciais do código) pelo link da sua página de pagamento.');
    return;
  }
  link = link.trim();
  if (!link) return;

  if (!/^https?:\/\//i.test(link)) {
    link = window.location.protocol + ':' + window.location.host + '/' + link;
  }
  window.open(link, '_blank', 'noopener,noreferrer');
}
</script>
