function cycle(el){
  const step = el.closest('[data-step]');
  const idx = parseInt(step.dataset.step,10);
  const q = SLOTS[idx];
  const arr = [...q.options];
  const pos = arr.findIndex(o=>o.k===el.dataset.key);
  let next = pos+1;
  if(e.key==='ArrowUp') next -= 1;
  if(next < 0) next = arr.length-1;
  if(next >= arr.length) next = 0;
  const target = arr[next];
  if(target.k !== el.dataset.key){
    select(target.k);
  }
}
