              return '<div class="option ' + cls + '" data-key="' + opt.k + '" data-num="' + i + '" role="radio" aria-checked="' + (cls === 'checked' ? 'true' : 'false') + '" tabindex="0">' +
                '<input type="radio" id="q' + i + '_' + opt.k + '" name="q' + i + '" value="' + opt.k + '" aria-label="' + escapeHtml(opt.label) + '">' +
